import Button from '@jetbrains/ring-ui-built/components/button/button'
import {memo, Suspense, useCallback, useContext, useMemo, useRef, useState} from 'react'

import {usePermission} from '../../../../hooks/usePermission'
import type {GetTestOccurrenceTreeApiArg} from '../../../../services/rest'
import {restApi} from '../../../../services/rest'
import {Permission, ROOT_PROJECT_ID, toTestOccurrenceId} from '../../../../types'
import type {ProjectId, BuildId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import type {Handle} from '../../../common/Tree/Tree'
import Tree from '../../../common/Tree/Tree'
import {getTreeNodes} from '../../../common/Tree/Tree.utils'
import {PipelinesTargetContext} from '../../../pages/PipelinesPages/contexts/targetContext'
import {isMuteInvestigateButtonEnabled} from '../../../pages/PipelinesPages/utils/featureToggles'
import InvestigationMuteButtons from '../InvestigationMuteButtons/InvestigationMuteButtons'
import {
  getTestOccurrencesLeavesHash,
  getTestOccurrencesNodesHash,
  getTestOccurrencesTreeNodes,
} from '../Tests.selectors'

import {generateTestsTree} from './TestsTree.utils'

import styles from './TestsTree.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  labelId: string
  className?: string
  projectId?: ProjectId
  buildId?: BuildId
  locator: string
  arg: GetTestOccurrenceTreeApiArg
  isSimple?: boolean
}

function TestsTree({labelId, className, projectId, buildId, locator, arg, isSimple}: Props) {
  const [fetchHandler] = restApi.endpoints.getTestOccurrenceTree.useLazyQuerySubscription()
  const treeRef = useRef<Handle>(null)
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const hasPermissionForInvestigation = usePermission(Permission.ASSIGN_INVESTIGATION, projectId)
  const hasPermissionForMute = usePermission(Permission.MANAGE_BUILD_PROBLEMS, projectId)
  const treeNodes = useAppSelector(state => getTestOccurrencesTreeNodes(state, arg))
  const leavesHash = useAppSelector(state => getTestOccurrencesLeavesHash(state, arg))
  const nodesHash = useAppSelector(state => getTestOccurrencesNodesHash(state, arg))
  const treeRoot = useMemo(
    () =>
      treeNodes != null
        ? generateTestsTree(treeNodes, leavesHash, locator, buildId, isSimple)
        : null,
    [treeNodes, leavesHash, locator, buildId, isSimple],
  )
  const treeRootChildren = treeRoot?.children ?? emptyArray
  const flatTreeNodes = useMemo(() => getTreeNodes(treeRootChildren), [treeRootChildren])
  const [checkedState, setCheckedState] = useState<string[]>([])

  const isAllowSelection =
    (hasPermissionForInvestigation || hasPermissionForMute) &&
    (!pipelinesTarget || isMuteInvestigateButtonEnabled)

  const defaultExpandedState = useMemo((): readonly string[] => {
    if (nodesHash[ROOT_PROJECT_ID]?.testCounters?.newFailed) {
      return flatTreeNodes
        .filter(node => nodesHash[node.value]?.testCounters?.newFailed)
        .map(node => `${node.value}`)
    }
    return flatTreeNodes.map(node => `${node.value}`)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const [expandedState, setExpandedState] = useState(defaultExpandedState)

  const onCheck = useCallback(
    (newCheckedState: readonly string[]) =>
      setCheckedState(newCheckedState.map(toTestOccurrenceId)),
    [],
  )
  const onExpand = useCallback(
    (newExpandedState: readonly string[]) => setExpandedState(newExpandedState),
    [],
  )
  const expandedAll = useMemo(
    () => flatTreeNodes.every(node => expandedState.includes(`${node.value}`)),
    [expandedState, flatTreeNodes],
  )

  const toggleExpand = useCallback(() => {
    if (expandedAll && treeRef.current?.onCollapseAll != null) {
      treeRef.current.onCollapseAll()
    }

    if (!expandedAll && treeRef.current?.onExpandAll != null) {
      treeRef.current.onExpandAll()
    }
  }, [expandedAll])

  const onAssignInvestigationOrMute = useCallback(() => {
    setCheckedState([])
    fetchHandler(arg)
  }, [arg, fetchHandler])

  return (
    <div className={className}>
      <Button className={styles.expandAll} onClick={toggleExpand}>
        {expandedAll ? 'Collapse all' : 'Expand all'}
      </Button>
      {(pipelinesTarget == null || isMuteInvestigateButtonEnabled) && (
        <Suspense>
          <InvestigationMuteButtons
            className={styles.investigationMuteButtons}
            projectId={projectId}
            testOccurrencesIds={checkedState}
            onAction={onAssignInvestigationOrMute}
          />
        </Suspense>
      )}
      <Tree
        labelId={labelId}
        id="overview-tests-tree"
        className={styles.tree}
        ref={treeRef}
        checkable={isAllowSelection}
        checked={checkedState}
        expanded={expandedState}
        nodes={treeRootChildren}
        checkAllButtonName={'All tests'}
        onCheck={onCheck}
        onExpand={onExpand}
      />
      {treeRoot?.footerComponent}
    </div>
  )
}

function TestsTreeContainer(props: Props) {
  return (
    <Suspense>
      <TestsTree {...props} />
    </Suspense>
  )
}

export default memo(TestsTreeContainer)
